package com.hrcoresystem.hrcore_api.modules.tenant.employees.application.usecase;
import com.hrcoresystem.hrcore_api.common.exception.*;
import com.hrcoresystem.hrcore_api.modules.identity.users.application.usecase.DeactivateTenantUserUseCase;
import com.hrcoresystem.hrcore_api.modules.platform.tenantsettings.application.service.TenantTimezoneService;
import com.hrcoresystem.hrcore_api.modules.tenant.employees.application.dto.*;
import com.hrcoresystem.hrcore_api.modules.tenant.employees.application.mapper.EmployeeMapper;
import com.hrcoresystem.hrcore_api.modules.tenant.employees.application.service.*;
import com.hrcoresystem.hrcore_api.modules.tenant.leaves.application.service.EmployeeLeaveTerminationService;
import com.hrcoresystem.hrcore_api.modules.tenant.departments.domain.repository.DepartmentRepository;
import com.hrcoresystem.hrcore_api.modules.tenant.employees.domain.model.*;
import com.hrcoresystem.hrcore_api.modules.tenant.employees.domain.repository.*;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class TerminateEmployeeUseCase {
 private final EmployeeRepository employees; private final EmployeeTerminationRepository terminations; private final EmployeePolicy policy; private final EmployeeMapper mapper; private final EmployeeAudit audit; private final DeactivateTenantUserUseCase deactivateUser; private final EmployeeTerminationReconciliationService reconciliation; private final TenantTimezoneService timezone; private final EmploymentPeriodService periods; private final EmployeeLeaveTerminationService leaveTermination; private final DepartmentRepository departments;
 @org.springframework.beans.factory.annotation.Autowired
 public TerminateEmployeeUseCase(EmployeeRepository employees,EmployeeTerminationRepository terminations,EmployeePolicy policy,EmployeeMapper mapper,EmployeeAudit audit,DeactivateTenantUserUseCase deactivateUser,EmployeeTerminationReconciliationService reconciliation,TenantTimezoneService timezone, EmploymentPeriodService periods, EmployeeLeaveTerminationService leaveTermination, DepartmentRepository departments){this.employees=employees;this.terminations=terminations;this.policy=policy;this.mapper=mapper;this.audit=audit;this.deactivateUser=deactivateUser;this.reconciliation=reconciliation;this.timezone=timezone;this.periods=periods;this.leaveTermination=leaveTermination;this.departments=departments;}
 public TerminateEmployeeUseCase(EmployeeRepository employees,EmployeeTerminationRepository terminations,EmployeePolicy policy,EmployeeMapper mapper,EmployeeAudit audit,DeactivateTenantUserUseCase deactivateUser,EmployeeTerminationReconciliationService reconciliation,TenantTimezoneService timezone, EmploymentPeriodService periods, EmployeeLeaveTerminationService leaveTermination){this(employees,terminations,policy,mapper,audit,deactivateUser,reconciliation,timezone,periods,leaveTermination,null);}
 @Transactional public EmployeeTerminationResponse execute(UUID id,TerminateEmployeeRequest request){policy.assertOperational();if(departments!=null)departments.lockHierarchy();Employee before=policy.requireForUpdate(id);if(before.employmentStatus()==EmploymentStatus.TERMINATED)throw new BusinessConflictException("La relación laboral del empleado ya fue finalizada");var date=timezone.today();if(request.effectiveDate()==null||!request.effectiveDate().equals(date))throw new BusinessException("La fecha efectiva debe coincidir con la fecha empresarial actual");if(request.effectiveDate().isBefore(before.hireDate()))throw new BusinessException("La fecha efectiva no puede ser anterior al ingreso");if(request.reason()==null||request.reason().trim().isBlank())throw new BusinessException("El motivo es obligatorio");UUID actor=policy.actorId();var period=periods.requireOpen(id);leaveTermination.reconcile(id,period.id(),date);var result=reconciliation.reconcile(before,date,request.reason().trim(),actor);Employee saved=employees.save(new Employee(before.id(),before.tenantUserId(),before.employeeNumber(),before.firstName(),before.middleName(),before.lastName(),before.secondLastName(),before.documentType(),before.documentNumber(),before.birthDate(),before.gender(),before.nationality(),before.personalEmail(),before.workEmail(),before.phone(),before.mobilePhone(),before.address(),before.hireDate(),date,EmploymentStatus.TERMINATED,before.createdBy(),actor,before.createdAt(),before.updatedAt()));terminations.save(new EmployeeTermination(null,id,period.id(),date,request.reason().trim(),actor,null));boolean deactivated=false;if(before.tenantUserId()!=null){deactivateUser.execute(before.tenantUserId());deactivated=true;}audit.record("EMPLOYEE","EMPLOYEE_TERMINATED",id,List.of("effectiveDate","reason"));return new EmployeeTerminationResponse(mapper.toResponse(saved),date,request.reason().trim(),result.terminatedContracts(),result.cancelledContracts(),result.closedAssignments(),result.cancelledAssignments(),result.closedShiftAssignments(),result.cancelledShiftAssignments(),deactivated);}
}
